import sys
import os
import subprocess
from collections import deque

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return 0

def process_template_line(line):
    line = line.strip()
    if not line or line.startswith('#'):
        return None
    result = []
    i = 0
    n = len(line)
    while i < n:
        if line.startswith('{{', i):
            j = line.find('}}', i)
            if j == -1:
                break
            expr = line[i+2:j]
            value = evaluate_expression(expr)
            result.append(str(value))
            i = j + 2
        else:
            result.append(line[i])
            i += 1
    return ''.join(result)

def run_commands(templates_file, output_file):
    with open(templates_file, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    commands = []
    for line in lines:
        cmd = process_template_line(line)
        if cmd:
            commands.append(cmd)

    with open(output_file, 'w', encoding='utf-8') as f:
        failed = 0
        for cmd in commands:
            result = subprocess.run(cmd, shell=True, text=True, capture_output=True)
            f.write(result.stdout)
            if result.returncode != 0:
                failed += 1

    print(f"ran {len(commands)} commands, {failed} failed")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(1)
    run_commands(sys.argv[1], sys.argv[2])

import sys
import subprocess
import re

def process_template(template):
    def replace_match(match):
        expr = match.group(1)
        try:
            return str(eval(expr, {'__builtins__': None}, {}))
        except:
            return match.group(0)  # Fallback to original if evaluation fails

    return re.sub(r'\{\{(.*?)\}\}', replace_match, template)

def main():
    if len(sys.argv) != 3:
        print("Usage: python templated_run.py <templates_file> <output_file>", file=sys.stderr)
        sys.exit(1)

    templates_file = sys.argv[1]
    output_file = sys.argv[2]

    with open(templates_file, 'r', encoding='utf-8') as f:
        lines = [line.strip() for line in f.readlines() if line.strip()]

    commands = []
    for line in lines:
        if not line.strip():
            continue
        commands.append(process_template(line))

    with open(output_file, 'w', encoding='utf-8') as f:
        for cmd in commands:
            result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
            f.write(result.stdout)

    print(f"ran {len(commands)} commands")

if __name__ == "__main__":
    main()

